import express from 'express';
import {
  saveQuotation,
  getAllQuotations,
  getQuotationById
} from '../controllers/quoteController.js';
import { verifyAdminToken } from '../middleware/auth.js';

const router = express.Router();

// Generate / save quote (can be requested by client or generated by admin)
router.post('/', saveQuotation);

// Protected admin registry
router.get('/', verifyAdminToken, getAllQuotations);
router.get('/:id', verifyAdminToken, getQuotationById);

export default router;
